/**
 * Wire payload for the `submit_phase_breakdown` submission tool. `stageIdx` and `phaseIdx` are the 2-D cursor of the phase the agent just expanded — both must echo back verbatim the cursor the agent received on the trigger payload (which the API derived from the already-accumulated phases). `plan` carries the steps-only payload to materialize for that phase. The workflow engine validates this payload at the wire boundary; malformed payloads are rejected before `processUserResponse` runs, and a mismatch between the echoed `(stageIdx, phaseIdx)` and the API\'s expected cursor synthesizes an ERROR-class completion rather than mutating accumulatedPhases.
 * @export
 * @interface PhaseBreakdownCompletionPayload
 */
export interface PhaseBreakdownCompletionPayload {
    /**
     * Zero-based stage index of the phase this payload expands. With `phaseIdx`, the 2-D cursor used as the `accumulatedPhases` key.
     * @type {number}
     * @memberof PhaseBreakdownCompletionPayload
     */
    'stageIdx': number;
    /**
     * Zero-based index of the journey step this payload expands within stage `stageIdx`\'s journey. With `stageIdx`, the 2-D cursor used as the `accumulatedPhases` key.
     * @type {number}
     * @memberof PhaseBreakdownCompletionPayload
     */
    'phaseIdx': number;
    /**
     *
     * @type {PhaseBreakdownPlan}
     * @memberof PhaseBreakdownCompletionPayload
     */
    'plan': PhaseBreakdownPlan;
}
/**
 * The structured plan the phase-breakdown agent emits for one journey step — a flat list of steps, each bound by `stageId` to the durable PlanStage the journey step belongs under. A phase emits steps only; it never authors stages, because the stage backbone is already durable from proposed-stages. Carried on the `DONE` completion\'s payload and accumulated on `PlanFromDesignDocFlowContext.accumulatedPhases` keyed by the `(stageIdx, phaseIdx)` cursor. The platform materializes every accumulated phase\'s steps in one transaction immediately before the FINALIZE transition fires; nothing is materialized during the agent loop.
 * @export
 * @interface PhaseBreakdownPlan
 */
export interface PhaseBreakdownPlan {
    /**
     * Steps to materialize under their durable stages. Each step\'s `stageId` must resolve to an existing PlanStage on the plan.
     * @type {Array<PhaseBreakdownStep>}
     * @memberof PhaseBreakdownPlan
     */
    'steps': Array<PhaseBreakdownStep>;
}
/**
 * One entry in the `priorPhases` trigger-payload array — the steps-only output an earlier phase-breakdown turn emitted, paired with the journey step that earlier turn was expanding and its 2-D `(stageIdx, phaseIdx)` cursor. The journey-step is included so the current-phase prompt can render each prior phase under a human-readable label without re-deriving it from `journeySteps` on FlowContext (the trigger payload no longer carries `journeySteps`).
 * @export
 * @interface PhaseBreakdownPriorPhase
 */
export interface PhaseBreakdownPriorPhase {
    /**
     * Zero-based stage index of the prior phase. With `phaseIdx`, the 2-D cursor that located the prior phase. Used only as a label here; the current phase\'s expected cursor is the top-level trigger field.
     * @type {number}
     * @memberof PhaseBreakdownPriorPhase
     */
    'stageIdx': number;
    /**
     * Zero-based index of the prior phase\'s journey step within stage `stageIdx`\'s journey. Used only as a label here; the current phase\'s expected cursor is the top-level trigger field.
     * @type {number}
     * @memberof PhaseBreakdownPriorPhase
     */
    'phaseIdx': number;
    /**
     *
     * @type {JourneyStep}
     * @memberof PhaseBreakdownPriorPhase
     */
    'journeyStep': JourneyStep;
    /**
     *
     * @type {PhaseBreakdownPlan}
     * @memberof PhaseBreakdownPriorPhase
     */
    'plan': PhaseBreakdownPlan;
}
/**
 * One step the phase-breakdown agent asks the platform to materialize under the durable PlanStage identified by `stageId`. `id` is a     stable UUID handle minted by the agent for the reviewed change set.     The platform materializes the step directly as a canonical STANDARD     Task; no PlanStep or duplicate backing entity is created.
 * @export
 * @interface PhaseBreakdownStep
 */
export interface PhaseBreakdownStep {
    /**
     * Stable UUID handle for this step within the reviewed atomic change set.
     * @type {string}
     * @memberof PhaseBreakdownStep
     */
    'id': string;
    /**
     * Explicit prerequisite step handles, directed from this dependent step to each prerequisite. Omission or an empty array declares no prerequisites; sequenceOrder never implies a dependency. References must resolve within the complete retained plan. Full-set review must preserve intended prerequisites, redirect references from merged steps to retained handles, and remove references only when the prerequisite is no longer intended.
     * @type {Array<string>}
     * @memberof PhaseBreakdownStep
     */
    'dependsOnStepIds'?: Array<string>;
    /**
     * UUID of the durable PlanStage this step is materialized under — the same `stageId` carried on the trigger\'s `journeyStep`. The stage is authored by proposed-stages and already exists; this phase emits no stages of its own. Materialization fails if this id does not resolve to a stage on the plan.
     * @type {string}
     * @memberof PhaseBreakdownStep
     */
    'stageId': string;
    /**
     * Short product-language title for the step. Follows the same title conventions `create_step` / `create_steps` document.
     * @type {string}
     * @memberof PhaseBreakdownStep
     */
    'title': string;
    /**
     * Product-language description of the step\'s intent and scope. Acceptance criteria belong on `acceptanceCriteria`, not here.
     * @type {string}
     * @memberof PhaseBreakdownStep
     */
    'description': string;
    /**
     * Per-step prose description of the concrete change this step delivers, bound to a file from the paired PHASE_GROUNDING report\'s `touchPoints`. The submission tool cross-validates that this string references at least one repo-relative path the agent named in that report, so each step the platform materializes points back at the touch point that motivated it.
     * @type {string}
     * @memberof PhaseBreakdownStep
     */
    'implementation': string;
    /**
     *
     * @type {PhaseBreakdownStepType}
     * @memberof PhaseBreakdownStep
     */
    'type': PhaseBreakdownStepType;
    /**
     * Required acceptance-criteria body for the step\'s backing entity. The value is one string containing newline-delimited markdown bullets (for example, `- First condition\\n- Second condition`), never a JSON array of strings. Every step must declare how its done-state will be verified; missing or empty is rejected at the submission boundary.
     * @type {string}
     * @memberof PhaseBreakdownStep
     */
    'acceptanceCriteria': string;
    /**
     * Zero-based ordering position of this step relative to its siblings under the same `stageId`.
     * @type {number}
     * @memberof PhaseBreakdownStep
     */
    'sequenceOrder': number;
    /**
     * Optional complete known set of platform Services that own or are modified by the work. Resolve every entry via `list_services` during the investigation pass. When supplied, materialization associates the backing task and PlanStep with every Service in the set. Omit only when Service scope is genuinely unresolved; never guess. Cross-Service work may remain one coherent step when its complete Service set is recorded.
     * @type {Array<string>}
     * @memberof PhaseBreakdownStep
     */
    'serviceIds'?: Array<string>;
    /**
     * A quoted excerpt or paraphrase of the design-doc passage that motivated this step — used to record a derived influence on the materialized proposal pointing back at the design doc. The agent must supply a non-empty value for every step; empty string is rejected at the submission boundary.
     * @type {string}
     * @memberof PhaseBreakdownStep
     */
    'designDocMotivation': string;
}


