/**
 *
 * @export
 * @interface PromptTypeResponseDto
 */
export interface PromptTypeResponseDto {
    /**
     * Three-state discriminator for where the conversation\'s workflow stands.  - agent-pending: the workflow is paused on an EXTERNAL_AGENT node and   the CLI owns the next turn — whether the workflow is still live on   that node or has gone but left a paused execution that resolves to an   agent node. This is the ONLY state in which nodeId and   triggerMessageId may be non-null; promptType carries the agent node\'s   own prompt-type. - live-non-agent: the workflow is still alive but parked on a node that   is not an EXTERNAL_AGENT — e.g. a QUESTIONS review gate awaiting the   user. The CLI has no pending turn, so nodeId and triggerMessageId are   null and promptType is the flow\'s terminalPromptType. Distinct from   terminal: the workflow has NOT finished, it is waiting on the user. - terminal: the workflow is complete, gone with no paused execution, or   was never attached. nodeId and triggerMessageId are null; promptType   is the flow\'s terminalPromptType, or null when the conversation has   no workflow or no registered flow template.
     * @type {string}
     * @memberof PromptTypeResponseDto
     */
    'workflowState': PromptTypeResponseDtoWorkflowStateEnum;
    /**
     * Prompt-type to use when dispatching the next CLI turn for this conversation. Resolves to the currently-paused EXTERNAL_AGENT node\'s promptType in the `agent-pending` workflowState, and to the flow\'s terminalPromptType in the `live-non-agent` and `terminal` states — except that it is null when the conversation has never been bound to a workflow or its workflow has no registered flow template (both `terminal`). Consumers should branch on workflowState rather than on this value, treating a null promptType as \"no workflow-defined prompt type\" and falling back to their default dispatch behavior.
     * @type {string}
     * @memberof PromptTypeResponseDto
     */
    'promptType': PromptTypeResponseDtoPromptTypeEnum | null;
    /**
     * ID of the EXTERNAL_AGENT node the conversation is currently paused on. Populated only when the workflow is active and the current node is EXTERNAL_AGENT. Null in every other case — no workflow attached, workflow complete or gone, current node is not EXTERNAL_AGENT. Consumers authoring completion messages back-reference this id so the server can match the paused flow execution without the caller having to cache it locally.
     * @type {string}
     * @memberof PromptTypeResponseDto
     */
    'nodeId': string | null;
    /**
     * Id of the open SYSTEM trigger message awaiting completion under nodeId. Null when nodeId is null, and also null when the projection finds no pending trigger for the current node (e.g. the trigger has already been completed by a later message). Pairs with nodeId to give callers everything they need to author the completion message (`completesExternalAgentNode.completesTriggerMessageId`) without relying on caller-side cached state.
     * @type {string}
     * @memberof PromptTypeResponseDto
     */
    'triggerMessageId': string | null;
}

export const PromptTypeResponseDtoWorkflowStateEnum = {
    AgentPending: 'agent-pending',
    LiveNonAgent: 'live-non-agent',
    Terminal: 'terminal'
} as const;

